#define INF 999999
int coinChange(int coins[],int nc,int amount){
    int dp[amount+1]; for(int i=0;i<=amount;i++)dp[i]=INF; dp[0]=0;
    for(int i=1;i<=amount;i++) for(int j=0;j<nc;j++) if(coins[j]<=i&&dp[i-coins[j]]+1<dp[i])dp[i]=dp[i-coins[j]]+1;
    return dp[amount]==INF?-1:dp[amount];
}
